-- Pumped: Curated Standard Strength Exercises Seed (266 exercises)
-- Generated by scripts/fetch-curated-exercises.mjs (idempotent upsert by slug)

INSERT INTO public.exercises (
  slug,
  name,
  muscle_group,
  secondary_muscles,
  equipment,
  tracking_type,
  media_gif_url,
  media_image_start_url,
  media_image_end_url,
  instructions,
  is_custom
)
VALUES
  ('barbell-bench-press', 'Barbell Bench Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-bench-press.gif', '/exercises/photos/barbell-bench-press-0.jpg', '/exercises/photos/barbell-bench-press-1.jpg', ARRAY['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.', 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], FALSE),
  ('incline-barbell-bench-press', 'Incline Barbell Bench Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-barbell-bench-press.gif', '/exercises/photos/incline-barbell-bench-press-0.jpg', '/exercises/photos/incline-barbell-bench-press-1.jpg', ARRAY['Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on you upper chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], FALSE),
  ('incline-dumbbell-press', 'Incline Dumbbell Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-dumbbell-press.gif', '/exercises/photos/incline-dumbbell-press-0.jpg', '/exercises/photos/incline-dumbbell-press-1.jpg', ARRAY['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.', 'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.', 'Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.']::text[], FALSE),
  ('dumbbell-bench-press', 'Dumbbell Bench Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-bench-press.gif', '/exercises/photos/dumbbell-bench-press-0.jpg', '/exercises/photos/dumbbell-bench-press-1.jpg', ARRAY['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.', 'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], FALSE),
  ('cable-chest-fly', 'Cable Chest Fly', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-chest-fly.gif', '/exercises/photos/cable-chest-fly-0.jpg', '/exercises/photos/cable-chest-fly-1.jpg', ARRAY['Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.', 'Lay flat on the bench and keep your feet on the ground.', 'Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.', 'Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.', 'Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.']::text[], FALSE),
  ('pec-deck-fly', 'Pec Deck Fly', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/pec-deck-fly.gif', '/exercises/photos/pec-deck-fly-0.jpg', '/exercises/photos/pec-deck-fly-1.jpg', ARRAY['Sit on the machine with your back flat on the pad.', 'Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.', 'Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.', 'Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('chest-dip', 'Chest Dip', 'chest'::public.muscle_group, ARRAY['triceps', 'shoulders']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'weighted_bodyweight'::public.tracking_type, '/exercises/gifs/chest-dip.gif', '/exercises/photos/chest-dip-0.jpg', '/exercises/photos/chest-dip-1.jpg', ARRAY['For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.', 'While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.', 'Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], FALSE),
  ('push-up', 'Push-Up', 'chest'::public.muscle_group, ARRAY['triceps', 'shoulders', 'core']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/push-up.gif', '/exercises/photos/push-up-0.jpg', '/exercises/photos/push-up-1.jpg', ARRAY['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[], FALSE),
  ('pull-up', 'Pull-Up', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'weighted_bodyweight'::public.tracking_type, '/exercises/gifs/pull-up.gif', '/exercises/photos/pull-up-0.jpg', '/exercises/photos/pull-up-1.jpg', ARRAY['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], FALSE),
  ('lat-pulldown', 'Lat Pulldown', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/lat-pulldown.gif', '/exercises/photos/lat-pulldown-0.jpg', '/exercises/photos/lat-pulldown-1.jpg', ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.']::text[], FALSE),
  ('barbell-bent-over-row', 'Barbell Bent-Over Row', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-bent-over-row.gif', '/exercises/photos/barbell-bent-over-row-0.jpg', '/exercises/photos/barbell-bent-over-row-1.jpg', ARRAY['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.', 'Then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('seated-cable-row', 'Seated Cable Row', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-cable-row.gif', '/exercises/photos/seated-cable-row-0.jpg', '/exercises/photos/seated-cable-row-1.jpg', ARRAY['For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('single-arm-dumbbell-row', 'Single-Arm Dumbbell Row', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-arm-dumbbell-row.gif', '/exercises/photos/single-arm-dumbbell-row-0.jpg', '/exercises/photos/single-arm-dumbbell-row-1.jpg', ARRAY['Choose a flat bench and place a dumbbell on each side of it.', 'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.', 'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.', 'Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.', 'Lower the resistance straight down to the starting position. Breathe in as you perform this step.']::text[], FALSE),
  ('chest-supported-row', 'Chest-Supported Dumbbell Row', 'back'::public.muscle_group, ARRAY['biceps', 'shoulders']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/chest-supported-row.gif', '/exercises/photos/chest-supported-row-0.jpg', '/exercises/photos/chest-supported-row-1.jpg', ARRAY['Using a neutral grip, lean into an incline bench.', 'Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.', 'Retract the shoulder blades and flex the elbows to row the dumbbells to your side.', 'Pause at the top of the motion, and then return to the starting position.']::text[], FALSE),
  ('conventional-deadlift', 'Conventional Deadlift', 'back'::public.muscle_group, ARRAY['hamstrings', 'glutes', 'forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/conventional-deadlift.gif', '/exercises/photos/conventional-deadlift-0.jpg', '/exercises/photos/conventional-deadlift-1.jpg', ARRAY['Stand in front of a loaded barbell.', 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.', 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.', 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.', 'Perform the amount of repetitions prescribed in the program.']::text[], FALSE),
  ('face-pull', 'Cable Face Pull', 'back'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/face-pull.gif', '/exercises/photos/face-pull-0.jpg', '/exercises/photos/face-pull-1.jpg', ARRAY['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[], FALSE),
  ('barbell-overhead-press', 'Barbell Overhead Press', 'shoulders'::public.muscle_group, ARRAY['triceps', 'core']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-overhead-press.gif', '/exercises/photos/barbell-overhead-press-0.jpg', '/exercises/photos/barbell-overhead-press-1.jpg', ARRAY['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.', 'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.']::text[], FALSE),
  ('seated-dumbbell-shoulder-press', 'Seated Dumbbell Shoulder Press', 'shoulders'::public.muscle_group, ARRAY['triceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-dumbbell-shoulder-press.gif', '/exercises/photos/seated-dumbbell-shoulder-press-0.jpg', '/exercises/photos/seated-dumbbell-shoulder-press-1.jpg', ARRAY['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.', 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.', 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.', 'Now, exhale and push the dumbbells upward until they touch at the top.', 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.']::text[], FALSE),
  ('dumbbell-lateral-raise', 'Dumbbell Lateral Raise', 'shoulders'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-lateral-raise.gif', '/exercises/photos/dumbbell-lateral-raise-0.jpg', '/exercises/photos/dumbbell-lateral-raise-1.jpg', ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.', 'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-lateral-raise', 'Cable Lateral Raise', 'shoulders'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-lateral-raise.gif', '/exercises/photos/cable-lateral-raise-0.jpg', '/exercises/photos/cable-lateral-raise-1.jpg', ARRAY['Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.', 'Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.', 'Bend forward while keeping your back flat and rest your torso on the thighs.', 'Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.', 'While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.']::text[], FALSE),
  ('reverse-pec-deck-fly', 'Reverse Pec Deck Fly', 'shoulders'::public.muscle_group, ARRAY['back']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/reverse-pec-deck-fly.gif', '/exercises/photos/reverse-pec-deck-fly-0.jpg', '/exercises/photos/reverse-pec-deck-fly-1.jpg', ARRAY['To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).', 'Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.', 'Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.', 'The arms should be elevated until they are parallel to the floor.', 'Feel the contraction and slowly lower the weights back down to the starting position while inhaling.']::text[], FALSE),
  ('dumbbell-front-raise', 'Dumbbell Front Raise', 'shoulders'::public.muscle_group, ARRAY['chest']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-front-raise.gif', '/exercises/photos/dumbbell-front-raise-0.jpg', '/exercises/photos/dumbbell-front-raise-1.jpg', ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.', 'Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.', 'Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.']::text[], FALSE),
  ('barbell-curl', 'Barbell Bicep Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-curl.gif', '/exercises/photos/barbell-curl-0.jpg', '/exercises/photos/barbell-curl-1.jpg', ARRAY['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-bicep-curl', 'Dumbbell Bicep Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-bicep-curl.gif', '/exercises/photos/dumbbell-bicep-curl-0.jpg', '/exercises/photos/dumbbell-bicep-curl-1.jpg', ARRAY['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('hammer-curl', 'Dumbbell Hammer Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/hammer-curl.gif', '/exercises/photos/hammer-curl-0.jpg', '/exercises/photos/hammer-curl-1.jpg', ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.', 'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('incline-dumbbell-curl', 'Incline Dumbbell Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-dumbbell-curl.gif', '/exercises/photos/incline-dumbbell-curl-0.jpg', '/exercises/photos/incline-dumbbell-curl-1.jpg', ARRAY['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-bicep-curl', 'Cable Bicep Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-bicep-curl.gif', '/exercises/photos/cable-bicep-curl-0.jpg', '/exercises/photos/cable-bicep-curl-1.jpg', ARRAY['Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the curl bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('preacher-curl', 'Preacher Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/preacher-curl.gif', '/exercises/photos/preacher-curl-0.jpg', '/exercises/photos/preacher-curl-1.jpg', ARRAY['To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.', 'With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-triceps-pushdown', 'Cable Rope Triceps Pushdown', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-triceps-pushdown.gif', '/exercises/photos/cable-triceps-pushdown-0.jpg', '/exercises/photos/cable-triceps-pushdown-1.jpg', ARRAY['Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.', 'Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('overhead-cable-triceps-extension', 'Overhead Cable Triceps Extension', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/overhead-cable-triceps-extension.gif', '/exercises/photos/overhead-cable-triceps-extension-0.jpg', '/exercises/photos/overhead-cable-triceps-extension-1.jpg', ARRAY['Attach a rope to the bottom pulley of the pulley machine.', 'Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.', 'Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('barbell-skullcrusher', 'Skullcrusher (Lying Triceps Extension)', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-skullcrusher.gif', '/exercises/photos/barbell-skullcrusher-0.jpg', '/exercises/photos/barbell-skullcrusher-1.jpg', ARRAY['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.', 'Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.', 'Lift the bar back to the starting position by extending the elbow and exhaling.', 'Repeat.']::text[], FALSE),
  ('dumbbell-overhead-triceps-extension', 'Dumbbell Overhead Triceps Extension', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-overhead-triceps-extension.gif', '/exercises/photos/dumbbell-overhead-triceps-extension-0.jpg', '/exercises/photos/dumbbell-overhead-triceps-extension-1.jpg', ARRAY['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.', 'Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.', 'Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.', 'Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.']::text[], FALSE),
  ('close-grip-bench-press', 'Close-Grip Bench Press', 'triceps'::public.muscle_group, ARRAY['chest', 'shoulders']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/close-grip-bench-press.gif', '/exercises/photos/close-grip-bench-press-0.jpg', '/exercises/photos/close-grip-bench-press-1.jpg', ARRAY['Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], FALSE),
  ('barbell-back-squat', 'Barbell Back Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings', 'core']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-back-squat.gif', '/exercises/photos/barbell-back-squat-0.jpg', '/exercises/photos/barbell-back-squat-1.jpg', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.', 'Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.']::text[], FALSE),
  ('front-squat', 'Barbell Front Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'core']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/front-squat.gif', '/exercises/photos/front-squat-0.jpg', '/exercises/photos/front-squat-1.jpg', ARRAY['To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.', 'Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position.']::text[], FALSE),
  ('leg-press', 'Leg Press', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/leg-press.gif', '/exercises/photos/leg-press-0.jpg', '/exercises/photos/leg-press-1.jpg', ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.', 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.', 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[], FALSE),
  ('bulgarian-split-squat', 'Dumbbell Bulgarian Split Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/bulgarian-split-squat.gif', '/exercises/photos/bulgarian-split-squat-0.jpg', '/exercises/photos/bulgarian-split-squat-1.jpg', ARRAY['Position yourself into a staggered stance with the rear foot elevated and front foot forward.', 'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.', 'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.', 'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.']::text[], FALSE),
  ('dumbbell-lunge', 'Dumbbell Lunge', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-lunge.gif', '/exercises/photos/dumbbell-lunge-0.jpg', '/exercises/photos/dumbbell-lunge-1.jpg', ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[], FALSE),
  ('leg-extension', 'Leg Extension', 'quads'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/leg-extension.gif', '/exercises/photos/leg-extension-0.jpg', '/exercises/photos/leg-extension-1.jpg', ARRAY['For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.', 'Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.', 'Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.', 'Repeat for the recommended amount of times.']::text[], FALSE),
  ('goblet-squat', 'Dumbbell Goblet Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'core']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/goblet-squat.gif', '/exercises/photos/goblet-squat-0.jpg', '/exercises/photos/goblet-squat-1.jpg', ARRAY['Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.', 'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.', 'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.']::text[], FALSE),
  ('romanian-deadlift', 'Barbell Romanian Deadlift', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/romanian-deadlift.gif', '/exercises/photos/romanian-deadlift-0.jpg', '/exercises/photos/romanian-deadlift-1.jpg', ARRAY['Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.', 'Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.', 'Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.', 'Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-romanian-deadlift', 'Dumbbell Romanian Deadlift', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-romanian-deadlift.gif', '/exercises/photos/dumbbell-romanian-deadlift-0.jpg', '/exercises/photos/dumbbell-romanian-deadlift-1.jpg', ARRAY['Grasp a couple of dumbbells holding them by your side at arm''s length.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('lying-leg-curl', 'Lying Leg Curl', 'hamstrings'::public.muscle_group, ARRAY['calves']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/lying-leg-curl.gif', '/exercises/photos/lying-leg-curl-0.jpg', '/exercises/photos/lying-leg-curl-1.jpg', ARRAY['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.', 'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.', 'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('seated-leg-curl', 'Seated Leg Curl', 'hamstrings'::public.muscle_group, ARRAY['calves']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-leg-curl.gif', '/exercises/photos/seated-leg-curl-0.jpg', '/exercises/photos/seated-leg-curl-1.jpg', ARRAY['Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.', 'Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.', 'As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('barbell-hip-thrust', 'Barbell Hip Thrust', 'glutes'::public.muscle_group, ARRAY['hamstrings', 'quads']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-hip-thrust.gif', '/exercises/photos/barbell-hip-thrust-0.jpg', '/exercises/photos/barbell-hip-thrust-1.jpg', ARRAY['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.', 'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.', 'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.']::text[], FALSE),
  ('cable-pull-through', 'Cable Pull-Through', 'glutes'::public.muscle_group, ARRAY['hamstrings']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-pull-through.gif', '/exercises/photos/cable-pull-through-0.jpg', '/exercises/photos/cable-pull-through-1.jpg', ARRAY['Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.', 'Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.']::text[], FALSE),
  ('glute-bridge', 'Barbell Glute Bridge', 'glutes'::public.muscle_group, ARRAY['hamstrings']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/glute-bridge.gif', '/exercises/photos/glute-bridge-0.jpg', '/exercises/photos/glute-bridge-1.jpg', ARRAY['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.', 'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.', 'Extend as far as possible, then reverse the motion to return to the starting position.']::text[], FALSE),
  ('hip-abduction-machine', 'Seated Hip Abduction Machine', 'glutes'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/hip-abduction-machine.gif', '/exercises/photos/hip-abduction-machine-0.jpg', '/exercises/photos/hip-abduction-machine-1.jpg', ARRAY['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them away from each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('standing-calf-raise', 'Standing Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/standing-calf-raise.gif', '/exercises/photos/standing-calf-raise-0.jpg', '/exercises/photos/standing-calf-raise-1.jpg', ARRAY['Adjust the padded lever of the calf raise machine to fit your height.', 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('seated-calf-raise', 'Seated Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-calf-raise.gif', '/exercises/photos/seated-calf-raise-0.jpg', '/exercises/photos/seated-calf-raise-1.jpg', ARRAY['Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.', 'Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.', 'Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.', 'Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.', 'Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.']::text[], FALSE),
  ('plank', 'Plank', 'core'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'duration'::public.tracking_type, '/exercises/gifs/plank.gif', '/exercises/photos/plank-0.jpg', '/exercises/photos/plank-1.jpg', ARRAY['Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.', 'Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.']::text[], FALSE),
  ('hanging-leg-raise', 'Hanging Leg Raise', 'core'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/hanging-leg-raise.gif', '/exercises/photos/hanging-leg-raise-0.jpg', '/exercises/photos/hanging-leg-raise-1.jpg', ARRAY['Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.', 'Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.', 'Go back slowly to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-crunch', 'Kneeling Cable Crunch', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-crunch.gif', '/exercises/photos/cable-crunch-0.jpg', '/exercises/photos/cable-crunch-1.jpg', ARRAY['Kneel below a high pulley that contains a rope attachment.', 'Grasp cable rope attachment and lower the rope until your hands are placed next to your face.', 'Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.', 'With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.', 'Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.']::text[], FALSE),
  ('ab-wheel-rollout', 'Ab Wheel Rollout', 'core'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'other'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/ab-wheel-rollout.gif', '/exercises/photos/ab-wheel-rollout-0.jpg', '/exercises/photos/ab-wheel-rollout-1.jpg', ARRAY['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.', 'Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[], FALSE),
  ('russian-twist', 'Russian Twist', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/russian-twist.gif', '/exercises/photos/russian-twist-0.jpg', '/exercises/photos/russian-twist-1.jpg', ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.', 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.', 'Twist your torso to the right side until your arms are parallel with the floor while breathing out.', 'Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-wrist-curl', 'Dumbbell Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-wrist-curl.gif', '/exercises/photos/dumbbell-wrist-curl-0.jpg', '/exercises/photos/dumbbell-wrist-curl-1.jpg', ARRAY['Start out by placing two dumbbells on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.']::text[], FALSE),
  ('decline-barbell-bench-press', 'Decline Barbell Bench Press', 'chest'::public.muscle_group, ARRAY['triceps', 'shoulders']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/decline-barbell-bench-press.gif', NULL, NULL, ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'As you breathe in, come down slowly until you feel the bar on your lower chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).', 'Repeat the movement for the prescribed amount of repetitions.']::text[], FALSE),
  ('wide-grip-barbell-bench-press', 'Wide-Grip Barbell Bench Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/wide-grip-barbell-bench-press.gif', NULL, NULL, ARRAY['Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your lower chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], FALSE),
  ('reverse-grip-incline-barbell-press', 'Reverse-Grip Incline Barbell Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/reverse-grip-incline-barbell-press.gif', NULL, NULL, ARRAY['Set up an incline bench at a 45-degree angle.', 'Lie down on the bench with your feet flat on the ground.', 'Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.', 'Pause for a moment when the barbell touches your chest.']::text[], FALSE),
  ('decline-dumbbell-bench-press', 'Decline Dumbbell Bench Press', 'chest'::public.muscle_group, ARRAY['triceps', 'shoulders']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/decline-dumbbell-bench-press.gif', NULL, NULL, ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..']::text[], FALSE),
  ('incline-neutral-dumbbell-press', 'Incline Neutral-Grip Dumbbell Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-neutral-dumbbell-press.gif', NULL, NULL, ARRAY['Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.', 'Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.', 'Press the dumbbells up and away from your body until your arms are fully extended.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('dumbbell-chest-fly', 'Dumbbell Chest Fly', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-chest-fly.gif', NULL, NULL, ARRAY['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.', 'Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[], FALSE),
  ('incline-dumbbell-fly', 'Incline Dumbbell Fly', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-dumbbell-fly.gif', NULL, NULL, ARRAY['Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.', 'Extend your arms above you with a slight bend at the elbows.', 'Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.', 'As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.', 'As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.']::text[], FALSE),
  ('decline-dumbbell-fly', 'Decline Dumbbell Fly', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/decline-dumbbell-fly.gif', NULL, NULL, ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[], FALSE),
  ('dumbbell-pullover', 'Dumbbell Pullover', 'chest'::public.muscle_group, ARRAY['back', 'triceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-pullover.gif', NULL, NULL, ARRAY['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.', 'Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.', 'While keeping your arms straight, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.']::text[], FALSE),
  ('low-cable-chest-fly', 'Low Cable Chest Fly', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/low-cable-chest-fly.gif', NULL, NULL, ARRAY['To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.', 'Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.', 'With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.', 'Return your arms back to the starting position after a brief pause.']::text[], FALSE),
  ('high-cable-crossover', 'High Cable Crossover', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/high-cable-crossover.gif', NULL, NULL, ARRAY['To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.', 'Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.']::text[], FALSE),
  ('decline-cable-fly', 'Decline Cable Fly', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/decline-cable-fly.gif', NULL, NULL, ARRAY['Adjust the cable machine to a decline position.', 'Stand facing away from the machine with your feet shoulder-width apart.', 'Hold the handles with your palms facing forward and your arms extended straight out in front of you.', 'Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.', 'Pause for a moment at the fully extended position, then slowly return to the starting position.']::text[], FALSE),
  ('incline-cable-fly', 'Incline Cable Fly', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-cable-fly.gif', NULL, NULL, ARRAY['To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).', 'Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.', 'With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.', 'With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.']::text[], FALSE),
  ('cable-chest-press', 'Cable Chest Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-chest-press.gif', NULL, NULL, ARRAY['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.', 'After pausing at full extension, return to th starting position, keeping tension on the cables.', 'You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.']::text[], FALSE),
  ('machine-chest-press', 'Machine Chest Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-chest-press.gif', NULL, NULL, ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.', 'Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[], FALSE),
  ('incline-machine-chest-press', 'Incline Machine Chest Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-machine-chest-press.gif', NULL, NULL, ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[], FALSE),
  ('decline-machine-chest-press', 'Decline Machine Chest Press', 'chest'::public.muscle_group, ARRAY['triceps', 'shoulders']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/decline-machine-chest-press.gif', NULL, NULL, ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[], FALSE),
  ('smith-bench-press', 'Smith Machine Bench Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-bench-press.gif', NULL, NULL, ARRAY['Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, lock the bar back in the rack.']::text[], FALSE),
  ('smith-incline-bench-press', 'Smith Machine Incline Bench Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-incline-bench-press.gif', NULL, NULL, ARRAY['Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your upper chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], FALSE),
  ('decline-push-up', 'Decline Push-Up', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps', 'core']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/decline-push-up.gif', NULL, NULL, ARRAY['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[], FALSE),
  ('chin-up', 'Chin-Up', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'weighted_bodyweight'::public.tracking_type, '/exercises/gifs/chin-up.gif', NULL, NULL, ARRAY['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.', 'As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], FALSE),
  ('wide-grip-pull-up', 'Wide-Grip Pull-Up', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'weighted_bodyweight'::public.tracking_type, '/exercises/gifs/wide-grip-pull-up.gif', NULL, NULL, ARRAY['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position.', 'Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], FALSE),
  ('weighted-pull-up', 'Weighted Pull-Up', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'weighted_bodyweight'::public.tracking_type, '/exercises/gifs/weighted-pull-up.gif', NULL, NULL, ARRAY['Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.', 'Hang from the bar with your arms fully extended and your body straight.', 'Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.']::text[], FALSE),
  ('assisted-pull-up', 'Assisted Pull-Up', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/assisted-pull-up.gif', NULL, NULL, ARRAY['Adjust the machine to your desired weight and height settings.', 'Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.', 'Hang with your arms fully extended and your feet off the ground.', 'Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.', 'Continue pulling until your chin is above the handles.']::text[], FALSE),
  ('inverted-row', 'Inverted Row', 'back'::public.muscle_group, ARRAY['biceps', 'forearms', 'core']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/inverted-row.gif', NULL, NULL, ARRAY['Position a bar in a rack to about waist height. You can also use a smith machine.', 'Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.', 'Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.', 'Pause at the top of the motion, and return yourself to the start position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('close-grip-lat-pulldown', 'Close-Grip V-Bar Lat Pulldown', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/close-grip-lat-pulldown.gif', NULL, NULL, ARRAY['Sit down on a pull-down machine with a V-Bar attached to the top pulley.', 'Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.', 'Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.', 'After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.']::text[], FALSE),
  ('underhand-lat-pulldown', 'Reverse-Grip Lat Pulldown', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/underhand-lat-pulldown.gif', NULL, NULL, ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.']::text[], FALSE),
  ('single-arm-lat-pulldown', 'Single-Arm Cable Lat Pulldown', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-arm-lat-pulldown.gif', NULL, NULL, ARRAY['Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.', 'Pull the handle down, squeezing your elbow to your side as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handle to the starting position.', 'For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.']::text[], FALSE),
  ('straight-arm-cable-pulldown', 'Straight-Arm Cable Pulldown', 'back'::public.muscle_group, ARRAY['triceps', 'core']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/straight-arm-cable-pulldown.gif', NULL, NULL, ARRAY['You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.', 'Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.', 'While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.', 'While keeping the arms straight, go back to the starting position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('wide-grip-seated-cable-row', 'Wide-Grip Seated Cable Row', 'back'::public.muscle_group, ARRAY['biceps', 'shoulders']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/wide-grip-seated-cable-row.gif', NULL, NULL, ARRAY['Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.', 'Grasp the handle with a wide overhand grip, palms facing down.', 'Keep your back straight and lean slightly forward from the hips.', 'Pull the handle towards your lower chest, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the contraction.']::text[], FALSE),
  ('single-arm-cable-row', 'Single-Arm Cable Row', 'back'::public.muscle_group, ARRAY['biceps', 'core']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-arm-cable-row.gif', NULL, NULL, ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.', 'Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.', 'Pause for a moment, then slowly extend your arm back to the starting position.']::text[], FALSE),
  ('barbell-pendlay-row', 'Barbell Pendlay Row', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-pendlay-row.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Bend forward at the hips, keeping your back straight and your chest up.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.', 'Lower the barbell back down to the starting position.']::text[], FALSE),
  ('reverse-grip-barbell-row', 'Reverse-Grip Barbell Row', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/reverse-grip-barbell-row.gif', NULL, NULL, ARRAY['Stand erect while holding a barbell with a supinated grip (palms facing up).', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-bent-over-row', 'Dumbbell Bent-Over Row', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-bent-over-row.gif', NULL, NULL, ARRAY['With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('barbell-pullover', 'Barbell Pullover', 'back'::public.muscle_group, ARRAY['chest', 'triceps']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-pullover.gif', NULL, NULL, ARRAY['Lie on a flat bench with a barbell using a shoulder grip width.', 'Hold the bar straight over your chest with a bend in your arms. This will be your starting position.', 'While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[], FALSE),
  ('machine-high-row', 'Machine High Row', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-high-row.gif', NULL, NULL, ARRAY['Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.', 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handles to the starting position.', 'For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[], FALSE),
  ('t-bar-row', 'T-Bar Row', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/t-bar-row.gif', NULL, NULL, ARRAY['Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.', 'Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.', 'Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.', 'Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.', 'After a brief pause, return to the starting position.']::text[], FALSE),
  ('machine-seated-row', 'Machine Seated Row', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-seated-row.gif', NULL, NULL, ARRAY['Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.', 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[], FALSE),
  ('machine-lat-pulldown', 'Machine Lat Pulldown', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-lat-pulldown.gif', NULL, NULL, ARRAY['Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.', 'Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.', 'Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.', 'Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.']::text[], FALSE),
  ('smith-bent-over-row', 'Smith Machine Bent-Over Row', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-bent-over-row.gif', NULL, NULL, ARRAY['Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.', 'Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.']::text[], FALSE),
  ('barbell-shrug', 'Barbell Shrug', 'back'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-shrug.gif', NULL, NULL, ARRAY['Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-shrug', 'Dumbbell Shrug', 'back'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-shrug.gif', NULL, NULL, ARRAY['Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.', 'Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.', 'Lower the dumbbells back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('smith-shrug', 'Smith Machine Shrug', 'back'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-shrug.gif', NULL, NULL, ARRAY['With the bar at thigh level, load an appropriate weight.', 'Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position.', 'Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement.', 'After a brief pause return the weight to the starting position.', 'Repeat for the desired number of repetitions before engaging the hooks to rack the weight.']::text[], FALSE),
  ('cable-shrug', 'Cable Shrug', 'back'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-shrug.gif', NULL, NULL, ARRAY['Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.', 'Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.', 'Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.', 'Lower the bar back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('back-hyperextension', 'Back Hyperextension', 'back'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/back-hyperextension.gif', NULL, NULL, ARRAY['Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.', 'Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.', 'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.', 'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.', 'Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.']::text[], FALSE),
  ('barbell-rack-pull', 'Barbell Rack Pull', 'back'::public.muscle_group, ARRAY['glutes', 'hamstrings', 'forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-rack-pull.gif', NULL, NULL, ARRAY['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.', 'With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.', 'Return the weight to the pins and repeat.']::text[], FALSE),
  ('dumbbell-arnold-press', 'Dumbbell Arnold Press', 'shoulders'::public.muscle_group, ARRAY['triceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-arnold-press.gif', NULL, NULL, ARRAY['Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.', 'Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.', 'Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.', 'After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-push-press', 'Dumbbell Push Press', 'shoulders'::public.muscle_group, ARRAY['triceps', 'quads']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-push-press.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.', 'Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.', 'Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('single-arm-dumbbell-shoulder-press', 'Single-Arm Dumbbell Shoulder Press', 'shoulders'::public.muscle_group, ARRAY['triceps', 'core']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-arm-dumbbell-shoulder-press.gif', NULL, NULL, ARRAY['Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.', 'Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.', 'Pause, and slowly return the weight to the starting position.']::text[], FALSE),
  ('seated-neutral-dumbbell-shoulder-press', 'Seated Neutral-Grip Shoulder Press', 'shoulders'::public.muscle_group, ARRAY['triceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-neutral-dumbbell-shoulder-press.gif', NULL, NULL, ARRAY['Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance.', 'Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise.', 'Slowly lift the dumbbell up until your arm is fully extended. This the starting position.', 'While inhaling lower the weight down until your arm is at a 90 degree angle again.', 'Feel the contraction for a second and then lift the weight back up towards the starting position while exhaling. Remember to hold on to the incline bench and keep your feet positioned to keep balance during the exercise.']::text[], FALSE),
  ('machine-shoulder-press', 'Machine Shoulder Press', 'shoulders'::public.muscle_group, ARRAY['triceps']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-shoulder-press.gif', NULL, NULL, ARRAY['Sit down on the Shoulder Press Machine and select the weight.', 'Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.', 'Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.', 'Lower the handles slowly back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('machine-military-press', 'Machine Overhead Military Press', 'shoulders'::public.muscle_group, ARRAY['triceps']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-military-press.gif', NULL, NULL, ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.', 'Press the handles upward by extending through the elbow.', 'After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[], FALSE),
  ('smith-shoulder-press', 'Smith Machine Overhead Press', 'shoulders'::public.muscle_group, ARRAY['triceps']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-shoulder-press.gif', NULL, NULL, ARRAY['To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.', 'Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position.', 'Slowly begin to lower the barbell until it is level with your chin while inhaling.', 'Then lift the barbell back to the starting position using your shoulders while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-shoulder-press', 'Cable Shoulder Press', 'shoulders'::public.muscle_group, ARRAY['triceps']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-shoulder-press.gif', NULL, NULL, ARRAY['Move the cables to the bottom of the towers and select an appropriate weight.', 'Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.', 'Keeping your head and chest up, extend through the elbow to press the handles directly over head.', 'After pausing at the top, return to the starting position and repeat.']::text[], FALSE),
  ('kettlebell-arnold-press', 'Kettlebell Arnold Press', 'shoulders'::public.muscle_group, ARRAY['triceps']::public.muscle_group[], 'kettlebell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/kettlebell-arnold-press.gif', NULL, NULL, ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.', 'Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.', 'Return the kettlebell to the starting position, with the palm facing in.']::text[], FALSE),
  ('kettlebell-thruster', 'Kettlebell Thruster', 'shoulders'::public.muscle_group, ARRAY['quads', 'glutes', 'triceps']::public.muscle_group[], 'kettlebell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/kettlebell-thruster.gif', NULL, NULL, ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.', 'Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.', 'At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.', 'As you begin the next repetition, return the weights to the shoulders.']::text[], FALSE),
  ('barbell-thruster', 'Barbell Thruster', 'shoulders'::public.muscle_group, ARRAY['quads', 'glutes', 'triceps']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-thruster.gif', NULL, NULL, ARRAY['Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.', 'Lower into a squat position by bending your knees and pushing your hips back.', 'As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.', 'Lower the barbell back to shoulder height as you lower back into the squat position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('seated-dumbbell-lateral-raise', 'Seated Dumbbell Lateral Raise', 'shoulders'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-dumbbell-lateral-raise.gif', NULL, NULL, ARRAY['Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms'' length. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('single-arm-cable-lateral-raise', 'Single-Arm Cable Lateral Raise', 'shoulders'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-arm-cable-lateral-raise.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, facing the cable machine.', 'Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.', 'Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arm back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.']::text[], FALSE),
  ('machine-lateral-raise', 'Machine Lateral Raise', 'shoulders'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-lateral-raise.gif', NULL, NULL, ARRAY['Adjust the seat height and position yourself on the machine with your back against the pad.', 'Grasp the handles with an overhand grip and keep your arms straight.', 'Exhale and raise your arms out to the sides until they are parallel to the floor.', 'Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('dumbbell-rear-delt-fly', 'Bent-Over Dumbbell Rear Delt Fly', 'shoulders'::public.muscle_group, ARRAY['back']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-rear-delt-fly.gif', NULL, NULL, ARRAY['Place a couple of dumbbells looking forward in front of a flat bench.', 'Sit on the end of the bench with your legs together and the dumbbells behind your calves.', 'Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position.', 'Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. (Note: avoid swinging the torso or bringing the arms back as opposed to the side.)', 'After a one second contraction at the top, slowly lower the dumbbells back to the starting position.']::text[], FALSE),
  ('cable-rear-delt-fly', 'Cable Rear Delt Fly', 'shoulders'::public.muscle_group, ARRAY['back']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-rear-delt-fly.gif', NULL, NULL, ARRAY['Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.', 'Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.', 'Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.', 'Pause at the end of the motion before returning the handles to the start position.']::text[], FALSE),
  ('barbell-front-raise', 'Barbell Front Raise', 'shoulders'::public.muscle_group, ARRAY['chest']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-front-raise.gif', NULL, NULL, ARRAY['To begin, stand straight with a barbell in your hands. You should grip the bar with palms facing down and a closer than shoulder width grip apart from each other.', 'Your feet should be shoulder width apart from each other. Your elbows should be slightly bent. This is the starting position.', 'Lift the barbell up until it is directly over your head while exhaling. Make sure to keep your elbows slightly bent when performing each repetition.', 'Once you feel the contraction, begin to lower the barbell back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-front-raise', 'Cable Front Raise', 'shoulders'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-front-raise.gif', NULL, NULL, ARRAY['Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.', 'Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms'' length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.', 'Now as you inhale lower the arm back down slowly to the starting position.', 'Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one.']::text[], FALSE),
  ('barbell-upright-row', 'Barbell Upright Row', 'shoulders'::public.muscle_group, ARRAY['back', 'biceps']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-upright-row.gif', NULL, NULL, ARRAY['Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.', 'Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-upright-row', 'Dumbbell Upright Row', 'shoulders'::public.muscle_group, ARRAY['back', 'biceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-upright-row.gif', NULL, NULL, ARRAY['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-upright-row', 'Cable Upright Row', 'shoulders'::public.muscle_group, ARRAY['back', 'biceps']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-upright-row.gif', NULL, NULL, ARRAY['Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('smith-upright-row', 'Smith Machine Upright Row', 'shoulders'::public.muscle_group, ARRAY['back', 'biceps']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-upright-row.gif', NULL, NULL, ARRAY['To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.', 'Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.', 'Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('ez-bar-curl', 'EZ-Bar Bicep Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/ez-bar-curl.gif', NULL, NULL, ARRAY['Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.', 'Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.', 'Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.', 'Then inhale and slowly lower the bar back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-concentration-curl', 'Dumbbell Concentration Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-concentration-curl.gif', NULL, NULL, ARRAY['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.', 'Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.', 'Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.']::text[], FALSE),
  ('dumbbell-preacher-curl', 'Dumbbell Preacher Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-preacher-curl.gif', NULL, NULL, ARRAY['Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.', 'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.', 'Switch arms and repeat the movement.']::text[], FALSE),
  ('dumbbell-zottman-curl', 'Dumbbell Zottman Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-zottman-curl.gif', NULL, NULL, ARRAY['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'Make sure the palms of the hands are facing each other. This will be your starting position.', 'While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a second as you squeeze the biceps.', 'Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.']::text[], FALSE),
  ('dumbbell-spider-curl', 'Dumbbell Spider Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-spider-curl.gif', NULL, NULL, ARRAY['Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.', 'Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.', 'Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.', 'Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.', 'Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.']::text[], FALSE),
  ('incline-dumbbell-hammer-curl', 'Incline Dumbbell Hammer Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-dumbbell-hammer-curl.gif', NULL, NULL, ARRAY['Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.', 'Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.', 'Continue to the top of the movement and pause, then slowly return to the start position.']::text[], FALSE),
  ('seated-dumbbell-curl', 'Seated Dumbbell Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-dumbbell-curl.gif', NULL, NULL, ARRAY['Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'Rotate the palms of the hands so that they are facing your torso. This will be your starting position.', 'While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('ez-bar-spider-curl', 'EZ-Bar Spider Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/ez-bar-spider-curl.gif', NULL, NULL, ARRAY['Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.', 'Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.', 'Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.', 'Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.', 'Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.']::text[], FALSE),
  ('barbell-reverse-curl', 'Barbell Reverse Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-reverse-curl.gif', NULL, NULL, ARRAY['Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('barbell-drag-curl', 'Barbell Drag Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-drag-curl.gif', NULL, NULL, ARRAY['Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.', 'As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.', 'Slowly go back to the starting position as you keep the bar in contact with the torso at all times.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-rope-hammer-curl', 'Cable Rope Hammer Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-rope-hammer-curl.gif', NULL, NULL, ARRAY['Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.', 'Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.', 'Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.', 'Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.', 'After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.']::text[], FALSE),
  ('single-arm-cable-curl', 'Single-Arm Cable Bicep Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-arm-cable-curl.gif', NULL, NULL, ARRAY['Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.', 'Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.', 'Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move.', 'Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-preacher-curl', 'Cable Preacher Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-preacher-curl.gif', NULL, NULL, ARRAY['Place a preacher bench about 2 feet in front of a pulley machine.', 'Attach a straight bar to the low pulley.', 'Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.', 'Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.', 'Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.']::text[], FALSE),
  ('cable-overhead-curl', 'High Cable Bicep Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-overhead-curl.gif', NULL, NULL, ARRAY['To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.', 'Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.', 'Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.', 'While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.', 'While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.']::text[], FALSE),
  ('machine-bicep-curl', 'Machine Bicep Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-bicep-curl.gif', NULL, NULL, ARRAY['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.', 'Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.', 'Pause at the top of the movement, and then slowly return the weight to the starting position.', 'Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[], FALSE),
  ('machine-preacher-curl', 'Machine Preacher Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-preacher-curl.gif', NULL, NULL, ARRAY['Sit down on the Preacher Curl Machine and select the weight.', 'Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.', 'Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.', 'Lower the handles slowly back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-straight-bar-pushdown', 'Cable Straight-Bar Pushdown', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-straight-bar-pushdown.gif', NULL, NULL, ARRAY['Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-vbar-pushdown', 'Cable V-Bar Triceps Pushdown', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-vbar-pushdown.gif', NULL, NULL, ARRAY['Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-reverse-grip-pushdown', 'Reverse-Grip Cable Pushdown', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-reverse-grip-pushdown.gif', NULL, NULL, ARRAY['Start by setting a bar attachment (straight or e-z) on a high pulley machine.', 'Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.', 'Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.', 'Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('single-arm-cable-pushdown', 'Single-Arm Cable Triceps Pushdown', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-arm-cable-pushdown.gif', NULL, NULL, ARRAY['Stand facing a cable machine with a straight bar attachment at chest height.', 'Grasp the bar with an overhand grip and step back to create tension in the cable.', 'Position your feet shoulder-width apart and slightly bend your knees.', 'Keep your back straight and core engaged throughout the exercise.', 'Start with your arm fully extended and perpendicular to the floor.']::text[], FALSE),
  ('cable-triceps-kickback', 'Cable Triceps Kickback', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-triceps-kickback.gif', NULL, NULL, ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Hold the cable handle with your right hand and step back to create tension in the cable.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Keep your upper arm close to your body and your elbow bent at a 90-degree angle.', 'Extend your forearm backward, straightening your arm fully.']::text[], FALSE),
  ('cable-incline-triceps-extension', 'Incline Cable Triceps Extension', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-incline-triceps-extension.gif', NULL, NULL, ARRAY['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.', 'Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.', 'Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.', 'Slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-triceps-kickback', 'Dumbbell Triceps Kickback', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-triceps-kickback.gif', NULL, NULL, ARRAY['Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.', 'Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.', 'After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], FALSE),
  ('seated-dumbbell-overhead-extension', 'Seated Two-Arm Dumbbell Overhead Extension', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-dumbbell-overhead-extension.gif', NULL, NULL, ARRAY['Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.', 'Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-tate-press', 'Dumbbell Tate Press', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-tate-press.gif', NULL, NULL, ARRAY['Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.', 'Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.', 'As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], FALSE),
  ('close-grip-dumbbell-bench-press', 'Close-Grip Dumbbell Bench Press', 'triceps'::public.muscle_group, ARRAY['chest', 'shoulders']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/close-grip-dumbbell-bench-press.gif', NULL, NULL, ARRAY['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.', 'Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.', 'Initiate the movement by lowering the dumbbell to your chest.', 'Return to the starting position by extending the elbows.']::text[], FALSE),
  ('barbell-jm-press', 'Barbell JM Press', 'triceps'::public.muscle_group, ARRAY['chest', 'shoulders']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-jm-press.gif', NULL, NULL, ARRAY['Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.', 'Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.', 'As you exhale, press the bar back up by using the triceps to perform a close grip bench press.', 'Now go back to the starting position and start over.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('ez-bar-close-grip-bench-press', 'EZ-Bar Close-Grip Bench Press', 'triceps'::public.muscle_group, ARRAY['chest', 'shoulders']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/ez-bar-close-grip-bench-press.gif', NULL, NULL, ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.', 'Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'Slowly lower the barbell towards your chest, keeping your elbows close to your body.', 'Pause for a moment when the barbell touches your chest.']::text[], FALSE),
  ('machine-triceps-dip', 'Machine Seated Triceps Dip', 'triceps'::public.muscle_group, ARRAY['chest', 'shoulders']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-triceps-dip.gif', NULL, NULL, ARRAY['Sit securely in a dip machine, select the weight and firmly grasp the handles.', 'Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.', 'As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.', 'Now slowly let your arms come back up to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('machine-triceps-extension', 'Machine Triceps Extension', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-triceps-extension.gif', NULL, NULL, ARRAY['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.', 'Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.', 'Pause at the completion of the movement, and then slowly return the weight to the starting position.', 'Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[], FALSE),
  ('smith-close-grip-bench-press', 'Smith Machine Close-Grip Bench Press', 'triceps'::public.muscle_group, ARRAY['chest', 'shoulders']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-close-grip-bench-press.gif', NULL, NULL, ARRAY['Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, lock the bar back in the rack.']::text[], FALSE),
  ('weighted-bench-dip', 'Weighted Bench Dip', 'triceps'::public.muscle_group, ARRAY['chest', 'shoulders']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'weighted_bodyweight'::public.tracking_type, '/exercises/gifs/weighted-bench-dip.gif', NULL, NULL, ARRAY['For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended.', 'The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exercise is best performed with a partner as placing the weight on your lap can be challenging and cause injury without assistance. This will be your starting position.', 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.', 'Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('diamond-push-up', 'Diamond Push-Up', 'triceps'::public.muscle_group, ARRAY['chest', 'shoulders']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/diamond-push-up.gif', NULL, NULL, ARRAY['Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[], FALSE),
  ('dumbbell-walking-lunge', 'Dumbbell Walking Lunge', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings', 'calves']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-walking-lunge.gif', '/exercises/photos/dumbbell-walking-lunge-0.jpg', '/exercises/photos/dumbbell-walking-lunge-1.jpg', ARRAY['Stand upright holding a dumbbell in each hand at arm''s length by your sides with feet hip-width apart.', 'Step forward with your right leg into a controlled stride, planting your foot flat on the floor ahead of you.', 'Lower your hips straight down until both knees bend to roughly 90 degrees, keeping your torso tall and front shin nearly vertical.', 'Drive through your front heel to bring your trailing leg directly forward into the next alternating step.', 'Continue walking smoothly forward for the target number of alternating strides while keeping your core braced.']::text[], FALSE),
  ('bodyweight-walking-lunge', 'Bodyweight Walking Lunge', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/bodyweight-walking-lunge.gif', NULL, NULL, ARRAY['Begin standing with your feet shoulder width apart and your hands on your hips.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[], FALSE),
  ('barbell-lunge', 'Barbell Lunge', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-lunge.gif', NULL, NULL, ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[], FALSE),
  ('barbell-walking-lunge', 'Barbell Walking Lunge', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-walking-lunge.gif', NULL, NULL, ARRAY['Begin standing with your feet shoulder width apart and a barbell across your upper back.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[], FALSE),
  ('barbell-reverse-lunge', 'Barbell Reverse Lunge', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-reverse-lunge.gif', NULL, NULL, ARRAY['Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.', 'Take a step backward with your right foot, landing on the ball of your foot.', 'Bend both knees to lower your body until your left thigh is parallel to the ground.', 'Push through your left heel to return to the starting position.', 'Repeat with the other leg.']::text[], FALSE),
  ('dumbbell-reverse-lunge', 'Dumbbell Reverse Lunge', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-reverse-lunge.gif', NULL, NULL, ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.', 'Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.', 'Now repeat with the opposite leg.']::text[], FALSE),
  ('dumbbell-contralateral-lunge', 'Dumbbell Contralateral Forward Lunge', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-contralateral-lunge.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', 'Take a step forward with your right foot, keeping your back straight and core engaged.', 'Lower your body by bending both knees until your right thigh is parallel to the ground.', 'Push through your right heel to return to the starting position.', 'Repeat with your left leg.']::text[], FALSE),
  ('dumbbell-squat', 'Dumbbell Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-squat.gif', NULL, NULL, ARRAY['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.', 'Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-step-up', 'Dumbbell Step-Up', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-step-up.gif', NULL, NULL, ARRAY['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[], FALSE),
  ('barbell-step-up', 'Barbell Step-Up', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-step-up.gif', NULL, NULL, ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[], FALSE),
  ('barbell-hack-squat', 'Barbell Hack Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-hack-squat.gif', NULL, NULL, ARRAY['Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.', 'Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('hack-squat-machine', 'Hack Squat Machine', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/hack-squat-machine.gif', NULL, NULL, ARRAY['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.', 'Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).', 'Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.']::text[], FALSE),
  ('single-leg-press', 'Single-Leg Press', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-leg-press.gif', NULL, NULL, ARRAY['Adjust the sled machine to a 45-degree angle.', 'Sit on the sled machine with your back against the pad and your feet on the footplate.', 'Place one foot on the footplate and extend your leg, pushing the sled away from you.', 'Slowly bend your knee and lower the sled back to the starting position.', 'Repeat with the other leg.']::text[], FALSE),
  ('smith-squat', 'Smith Machine Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-squat.gif', NULL, NULL, ARRAY['To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.']::text[], FALSE),
  ('smith-hack-squat', 'Smith Machine Hack Squat', 'quads'::public.muscle_group, ARRAY['glutes']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-hack-squat.gif', NULL, NULL, ARRAY['Adjust the barbell on the smith machine to an appropriate height for your body.', 'Stand with your feet shoulder-width apart, toes slightly pointed outwards.', 'Position yourself under the barbell, resting it on your upper traps and shoulders.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Engage your core and keep your chest up as you unrack the barbell.']::text[], FALSE),
  ('smith-split-squat', 'Smith Machine Split Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-split-squat.gif', NULL, NULL, ARRAY['To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Position your legs by placing one foot slightly forward under the bar and extending your other leg back and place the top of your foot on the bench. This will be your starting position', 'Begin to slowly lower the bar by bending the knee as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calf becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knee should make an imaginary straight line with the toes that is perpendicular to the front. If your knee is past that imaginary line (if it is past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten your leg again and go back to the starting position.']::text[], FALSE),
  ('barbell-split-squat', 'Barbell Split Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-split-squat.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, holding a barbell across your upper back.', 'Take a large step forward with one leg, keeping your torso upright.', 'Lower your body by bending your front knee and hip, while keeping your back leg straight.', 'Continue lowering until your front thigh is parallel to the ground.', 'Pause for a moment, then push through your front heel to return to the starting position.']::text[], FALSE),
  ('bodyweight-split-squat', 'Bodyweight Split Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/bodyweight-split-squat.gif', NULL, NULL, ARRAY['Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.', 'As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg.']::text[], FALSE),
  ('barbell-high-bar-squat', 'Barbell High-Bar Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings', 'core']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-high-bar-squat.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, toes slightly turned out.', 'Place the barbell on your upper back, resting it on your traps.', 'Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.', 'Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Drive through your heels to stand back up, extending your hips and knees.']::text[], FALSE),
  ('barbell-overhead-squat', 'Barbell Overhead Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'shoulders', 'core']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-overhead-squat.gif', NULL, NULL, ARRAY['Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.', 'Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.', 'Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.', 'Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.', 'Now use your feet and legs to help bring the weight back up to the starting position while exhaling.']::text[], FALSE),
  ('barbell-zercher-squat', 'Barbell Zercher Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'core', 'biceps']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-zercher-squat.gif', NULL, NULL, ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.', 'Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position.']::text[], FALSE),
  ('kettlebell-goblet-squat', 'Kettlebell Goblet Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'core']::public.muscle_group[], 'kettlebell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/kettlebell-goblet-squat.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.', 'Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.', 'Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('sissy-squat', 'Sissy Squat', 'quads'::public.muscle_group, ARRAY['core']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/sissy-squat.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart and your toes pointing slightly outward.', 'Hold onto a stable object for balance if needed.', 'Slowly lower your body by bending your knees and leaning back, keeping your torso upright.', 'Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.', 'Pause for a moment, then push through your heels to return to the starting position.']::text[], FALSE),
  ('stiff-leg-barbell-deadlift', 'Stiff-Legged Barbell Deadlift', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/stiff-leg-barbell-deadlift.gif', NULL, NULL, ARRAY['Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.', 'Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('stiff-leg-dumbbell-deadlift', 'Stiff-Legged Dumbbell Deadlift', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/stiff-leg-dumbbell-deadlift.gif', NULL, NULL, ARRAY['Grasp a couple of dumbbells holding them by your side at arm''s length.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('single-leg-dumbbell-rdl', 'Single-Leg Dumbbell RDL', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'core']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-leg-dumbbell-rdl.gif', NULL, NULL, ARRAY['Stand with your feet hip-width apart, holding a dumbbell in your right hand.', 'Shift your weight onto your left leg and lift your right foot slightly off the ground.', 'Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.', 'At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.', 'Lower the dumbbell until your torso and right leg are parallel to the ground.']::text[], FALSE),
  ('single-leg-barbell-rdl', 'Single-Leg Barbell RDL', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'core']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-leg-barbell-rdl.gif', NULL, NULL, ARRAY['Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.', 'Shift your weight onto your left foot and lift your right foot slightly off the ground.', 'Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.', 'Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.', 'Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.']::text[], FALSE),
  ('barbell-good-morning', 'Barbell Good Morning', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-good-morning.gif', NULL, NULL, ARRAY['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.', 'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.', 'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.']::text[], FALSE),
  ('machine-seated-good-morning', 'Machine Seated Good Morning', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-seated-good-morning.gif', NULL, NULL, ARRAY['Adjust the seat height so that your hips are slightly higher than your knees.', 'Sit on the machine with your back against the pad and your feet flat on the footrests.', 'Grasp the handles or the sides of the seat for stability.', 'Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.', 'Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.']::text[], FALSE),
  ('smith-good-morning', 'Smith Machine Good Morning', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-good-morning.gif', NULL, NULL, ARRAY['Start by standing with your feet shoulder-width apart, toes pointing forward.', 'Place the barbell across your upper back, resting it on your traps.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.', 'Engage your glutes and hamstrings to raise your torso back up to the starting position.']::text[], FALSE),
  ('kneeling-leg-curl-machine', 'Kneeling Leg Curl Machine', 'hamstrings'::public.muscle_group, ARRAY['calves']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/kneeling-leg-curl-machine.gif', NULL, NULL, ARRAY['Adjust the machine to fit your body and select the desired weight.', 'Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.', 'Grasp the handles or the sides of the machine for stability.', 'Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.', 'Pause for a moment at the top of the movement, squeezing your hamstrings.']::text[], FALSE),
  ('glute-ham-raise', 'Glute-Ham Raise', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/glute-ham-raise.gif', NULL, NULL, ARRAY['Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.', 'Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.', 'Return to the starting position, keeping your descent under control.']::text[], FALSE),
  ('nordic-hamstring-curl', 'Nordic Hamstring Curl', 'hamstrings'::public.muscle_group, ARRAY['glutes']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/nordic-hamstring-curl.gif', NULL, NULL, ARRAY['Lie flat on your back on a mat or bench with your legs extended.', 'Place your hands by your sides or under your glutes for support.', 'Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.', 'Pause for a moment at the top, then slowly lower your legs back to the starting position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('dumbbell-lying-leg-curl', 'Dumbbell Lying Leg Curl', 'hamstrings'::public.muscle_group, ARRAY['calves']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-lying-leg-curl.gif', NULL, NULL, ARRAY['Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.', 'Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('power-clean', 'Barbell Power Clean', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back', 'shoulders']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/power-clean.gif', NULL, NULL, ARRAY['Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.', 'Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.', 'Place the bar about 1 inch in front of your shins and over the balls of your feet.', 'Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.', 'Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.']::text[], FALSE),
  ('barbell-sumo-deadlift', 'Barbell Sumo Deadlift', 'glutes'::public.muscle_group, ARRAY['hamstrings', 'quads', 'back']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-sumo-deadlift.gif', NULL, NULL, ARRAY['Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[], FALSE),
  ('trap-bar-deadlift', 'Trap Bar Deadlift', 'glutes'::public.muscle_group, ARRAY['quads', 'hamstrings', 'back']::public.muscle_group[], 'other'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/trap-bar-deadlift.gif', NULL, NULL, ARRAY['For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.', 'Lower your hips, look forward with your head and keep your chest up.', 'Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.', 'At the completion of the movement, lower the weight back to the ground under control.']::text[], FALSE),
  ('dumbbell-deadlift', 'Dumbbell Deadlift', 'glutes'::public.muscle_group, ARRAY['hamstrings', 'back']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-deadlift.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, toes pointing forward.', 'Hold a dumbbell in each hand, palms facing your body, arms extended downwards.', 'Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.', 'Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('cable-deadlift', 'Cable Deadlift', 'glutes'::public.muscle_group, ARRAY['hamstrings', 'back']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-deadlift.gif', NULL, NULL, ARRAY['Stand facing the cable machine with your feet shoulder-width apart.', 'Bend at the hips and knees, lowering your torso until your back is parallel to the ground.', 'Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.', 'Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.', 'Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.']::text[], FALSE),
  ('smith-deadlift', 'Smith Machine Deadlift', 'glutes'::public.muscle_group, ARRAY['hamstrings', 'back']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-deadlift.gif', NULL, NULL, ARRAY['Set up the smith machine with the bar at hip height.', 'Stand with your feet shoulder-width apart, toes pointing slightly outward.', 'Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.', 'Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.', 'Stand up straight, fully extending your hips and knees.']::text[], FALSE),
  ('smith-sumo-squat', 'Smith Machine Sumo Squat', 'glutes'::public.muscle_group, ARRAY['quads', 'hamstrings']::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-sumo-squat.gif', NULL, NULL, ARRAY['Set up the smith machine with the barbell at hip height.', 'Stand with your feet wider than shoulder-width apart, toes pointing outwards.', 'Position yourself under the barbell, resting it on your upper back and shoulders.', 'Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.', 'Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.']::text[], FALSE),
  ('kettlebell-swing', 'Kettlebell Swing', 'glutes'::public.muscle_group, ARRAY['hamstrings', 'core', 'back']::public.muscle_group[], 'kettlebell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/kettlebell-swing.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, toes pointed slightly outward.', 'Hold the kettlebell with both hands in front of your body, arms extended.', 'Bend your knees slightly and hinge at the hips, pushing your butt back.', 'Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.', 'Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.']::text[], FALSE),
  ('cable-glute-kickback', 'Cable Glute Kickback', 'glutes'::public.muscle_group, ARRAY['hamstrings']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-glute-kickback.gif', NULL, NULL, ARRAY['Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.', 'As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.', 'Go back to the initial position as you inhale and now repeat with the left leg.', 'Continue to alternate legs until all of the recommended repetitions have been performed.']::text[], FALSE),
  ('cable-hip-adduction', 'Cable Hip Adduction', 'glutes'::public.muscle_group, ARRAY['quads']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-hip-adduction.gif', NULL, NULL, ARRAY['Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.', 'Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.', 'Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.', 'Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.', 'Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.']::text[], FALSE),
  ('hip-adduction-machine', 'Seated Hip Adduction Machine', 'glutes'::public.muscle_group, ARRAY['quads']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/hip-adduction-machine.gif', NULL, NULL, ARRAY['To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them towards each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('machine-reverse-hyperextension', 'Machine Reverse Hyperextension', 'glutes'::public.muscle_group, ARRAY['hamstrings', 'back']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-reverse-hyperextension.gif', NULL, NULL, ARRAY['Adjust the leverage machine to fit your body and secure your feet in the foot pads.', 'Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.', 'Cross your arms over your chest or place them behind your head.', 'Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.']::text[], FALSE),
  ('barbell-lateral-lunge', 'Barbell Lateral Lunge', 'glutes'::public.muscle_group, ARRAY['quads', 'hamstrings']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-lateral-lunge.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, holding a barbell across your upper back.', 'Take a big step to the side with your right foot, keeping your left foot planted.', 'Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.', 'Push off with your right foot and return to the starting position.', 'Repeat on the other side, stepping with your left foot.']::text[], FALSE),
  ('curtsy-lunge', 'Curtsy Lunge', 'glutes'::public.muscle_group, ARRAY['quads', 'hamstrings']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/curtsy-lunge.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart.', 'Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.', 'Bend both knees as if you were curtsying, lowering your body towards the ground.', 'Keep your torso upright and your weight on your front foot.', 'Push through your front foot to return to the starting position.']::text[], FALSE),
  ('bodyweight-glute-bridge', 'Bodyweight Glute Bridge', 'glutes'::public.muscle_group, ARRAY['hamstrings', 'core']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/bodyweight-glute-bridge.gif', NULL, NULL, ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your arms by your sides, palms facing down.', 'Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.', 'Pause for a moment at the top, squeezing your glutes.', 'Slowly lower your hips back down to the starting position.']::text[], FALSE),
  ('barbell-standing-calf-raise', 'Barbell Standing Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-standing-calf-raise.gif', NULL, NULL, ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck).', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: For better range of motion you may also place the ball of your feet on a wooden block but be careful as this option requires more balance and a sturdy block.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.']::text[], FALSE),
  ('barbell-seated-calf-raise', 'Barbell Seated Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-seated-calf-raise.gif', NULL, NULL, ARRAY['Place a block about 12 inches in front of a flat bench.', 'Sit on the bench and place the ball of your feet on the block.', 'Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.', 'Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.', 'After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.']::text[], FALSE),
  ('dumbbell-standing-calf-raise', 'Dumbbell Standing Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-standing-calf-raise.gif', NULL, NULL, ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.', 'With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.', 'As you inhale, go back to the starting position by slowly lowering the heels.', 'Repeat for the recommended amount of times.']::text[], FALSE),
  ('single-leg-dumbbell-calf-raise', 'Single-Leg Dumbbell Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-leg-dumbbell-calf-raise.gif', NULL, NULL, ARRAY['Stand on the edge of a step or platform with your heels hanging off and your toes on the step.', 'Hold a dumbbell in one hand and place your other hand on a wall or railing for support.', 'Raise your heel as high as possible, lifting your body up onto your toes.', 'Pause for a moment at the top, then slowly lower your heel back down below the step.', 'Repeat for the desired number of repetitions, then switch to the other leg.']::text[], FALSE),
  ('dumbbell-seated-calf-raise', 'Dumbbell Seated Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-seated-calf-raise.gif', NULL, NULL, ARRAY['Place a block on the floor about 12 inches from a flat bench.', 'Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.', 'Now place the ball of your left foot on the block. This will be your starting position.', 'Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.', 'Slowly return to the starting position, stretching as far down as possible.']::text[], FALSE),
  ('leg-press-calf-raise', 'Leg Press Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/leg-press-calf-raise.gif', NULL, NULL, ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('single-leg-press-calf-raise', 'Single-Leg Press Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-leg-press-calf-raise.gif', NULL, NULL, ARRAY['Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.', 'Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.', 'Place your toes and the balls of your feet on the sled, keeping your heels off.', 'Push the sled forward by extending your ankles, keeping your knees slightly bent.', 'Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.']::text[], FALSE),
  ('hack-squat-calf-raise', 'Hack Squat Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/hack-squat-calf-raise.gif', NULL, NULL, ARRAY['Adjust the sled machine to a comfortable weight.', 'Stand on the sled machine with your toes on the platform and your heels hanging off.', 'Hold onto the handles for stability.', 'Raise your heels as high as possible by pushing through the balls of your feet.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.']::text[], FALSE),
  ('machine-donkey-calf-raise', 'Machine Donkey Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-donkey-calf-raise.gif', NULL, NULL, ARRAY['For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.', 'Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('smith-calf-raise', 'Smith Machine Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-calf-raise.gif', NULL, NULL, ARRAY['Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.', 'Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.', 'Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.', 'Return slowly to the starting position as you breathe in while lowering your heels.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-standing-calf-raise', 'Cable Standing Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-standing-calf-raise.gif', NULL, NULL, ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Hold onto the cable machine handles or attach a cable ankle strap to your ankles.', 'Raise your heels off the ground by extending your ankles as high as possible.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('bodyweight-standing-calf-raise', 'Bodyweight Standing Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/bodyweight-standing-calf-raise.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, toes pointing forward.', 'Place your hands on a wall or stable surface for balance.', 'Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('weighted-plank', 'Weighted Plank', 'core'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'other'::public.equipment_type, 'duration'::public.tracking_type, '/exercises/gifs/weighted-plank.gif', NULL, NULL, ARRAY['Start by lying face down on the floor.', 'Place your forearms on the ground, with your elbows directly under your shoulders.', 'Extend your legs straight out behind you, with your toes on the ground.', 'Engage your core and lift your body off the ground, balancing on your forearms and toes.', 'Keep your body in a straight line from your head to your heels.']::text[], FALSE),
  ('hanging-straight-leg-raise', 'Hanging Straight-Leg Raise', 'core'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/hanging-straight-leg-raise.gif', NULL, NULL, ARRAY['Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar.', 'Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position.', 'Pull your legs up as you exhale until you almost touch your shins with the bar above you. Tip: Try to straighten your legs as much as possible while at the top.', 'Lower your legs as slowly as possible until you reach the starting position. Tip: Avoid swinging and using momentum at all times.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('hanging-oblique-knee-raise', 'Hanging Oblique Knee Raise', 'core'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/hanging-oblique-knee-raise.gif', NULL, NULL, ARRAY['Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', 'Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat on the other side, twisting your torso in the opposite direction.', 'Continue alternating sides for the desired number of repetitions.']::text[], FALSE),
  ('captains-chair-leg-raise', 'Captain''s Chair Leg Raise', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/captains-chair-leg-raise.gif', NULL, NULL, ARRAY['Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.', 'Keep your upper body stable and your back straight.', 'Engage your abs and lift your legs up in front of you, keeping them straight.', 'Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.']::text[], FALSE),
  ('lying-leg-raise', 'Lying Leg Raise', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/lying-leg-raise.gif', NULL, NULL, ARRAY['Lie with your back flat on a bench and your legs extended in front of you off the end.', 'Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.', 'As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.', 'Now, as you inhale, slowly lower your legs back down to the starting position.']::text[], FALSE),
  ('reverse-crunch', 'Reverse Crunch', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/reverse-crunch.gif', NULL, NULL, ARRAY['Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.', 'Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.', 'While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.', 'Hold the contraction for a second and move your legs back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('decline-crunch', 'Decline Crunch', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/decline-crunch.gif', NULL, NULL, ARRAY['Secure your legs at the end of the decline bench and lie down.', 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.', 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.', 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.']::text[], FALSE),
  ('weighted-decline-sit-up', 'Weighted Decline Sit-Up', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'other'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/weighted-decline-sit-up.gif', NULL, NULL, ARRAY['Lie flat on a decline bench with your feet secured under the foot pads.', 'Place your hands behind your head or across your chest.', 'Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.']::text[], FALSE),
  ('bodyweight-crunch', 'Bodyweight Crunch', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/bodyweight-crunch.gif', NULL, NULL, ARRAY['Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.', 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.', 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.', 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.']::text[], FALSE),
  ('bicycle-crunch', 'Bicycle Crunch', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/bicycle-crunch.gif', NULL, NULL, ARRAY['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.', 'Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.', 'Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.', 'Go back to the initial position as you breathe in.', 'Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.']::text[], FALSE),
  ('dead-bug', 'Dead Bug', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/dead-bug.gif', NULL, NULL, ARRAY['Begin lying on your back with your hands extended above you toward the ceiling.', 'Bring your feet, knees, and hips up to 90 degrees.', 'Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.', 'Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.', 'Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.']::text[], FALSE),
  ('v-up-jackknife', 'V-Up (Jackknife Sit-Up)', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/v-up-jackknife.gif', NULL, NULL, ARRAY['Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.', 'As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.', 'While inhaling, lower your arms and legs back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-woodchopper-twist', 'Cable Woodchopper Twist', 'core'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-woodchopper-twist.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart, facing the cable machine.', 'Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.', 'Engage your core and twist your torso to the right, pulling the cable across your body.', 'Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.', 'Slowly return to the starting position, resisting the cable''s pull.']::text[], FALSE),
  ('cable-reverse-crunch', 'Cable Reverse Crunch', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-reverse-crunch.gif', NULL, NULL, ARRAY['Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.', 'Sit down with your feet toward the pulley and attach the cable to your ankles.', 'Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.', 'With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.', 'Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.']::text[], FALSE),
  ('standing-cable-crunch', 'Standing Cable Crunch', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/standing-cable-crunch.gif', NULL, NULL, ARRAY['Connect a standard handle on a tower, and move the cable to the lowest pulley position.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.', 'With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.', 'In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.', 'Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.']::text[], FALSE),
  ('cable-side-bend', 'Cable Side Bend', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-side-bend.gif', NULL, NULL, ARRAY['Stand with your feet shoulder-width apart and grasp the cable handle with one hand.', 'Keep your back straight and your core engaged.', 'Slowly bend sideways at the waist, lowering the cable handle towards your knee.', 'Pause for a moment, then return to the starting position.', 'Repeat on the other side.']::text[], FALSE),
  ('dumbbell-side-bend', 'Dumbbell Side Bend', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-side-bend.gif', NULL, NULL, ARRAY['Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions and then change hands.']::text[], FALSE),
  ('machine-ab-crunch', 'Machine Ab Crunch', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/machine-ab-crunch.gif', NULL, NULL, ARRAY['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.', 'At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.', 'After a second pause, slowly return to the starting position as you breathe in.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], FALSE),
  ('barbell-landmine-twist', 'Barbell Landmine Twist', 'core'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-landmine-twist.gif', NULL, NULL, ARRAY['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.', 'Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.', 'Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.', 'Reverse the motion to swing the weight all the way to the opposite side.', 'Continue alternating the movement until the set is complete.']::text[], FALSE),
  ('barbell-wrist-curl', 'Barbell Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-wrist-curl.gif', NULL, NULL, ARRAY['Start out by placing a barbell on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.']::text[], FALSE),
  ('barbell-reverse-wrist-curl', 'Barbell Reverse Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-reverse-wrist-curl.gif', NULL, NULL, ARRAY['Start out by placing a barbell on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.']::text[], FALSE),
  ('behind-back-barbell-wrist-curl', 'Behind-the-Back Barbell Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/behind-back-barbell-wrist-curl.gif', NULL, NULL, ARRAY['Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.', 'You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.', 'While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.', 'Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('barbell-finger-curl', 'Barbell Finger Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-finger-curl.gif', NULL, NULL, ARRAY['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.', 'Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.', 'Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.']::text[], FALSE),
  ('dumbbell-reverse-wrist-curl', 'Dumbbell Reverse Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-reverse-wrist-curl.gif', NULL, NULL, ARRAY['Start out by placing two dumbbells on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.']::text[], FALSE),
  ('dumbbell-finger-curl', 'Dumbbell Finger Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-finger-curl.gif', NULL, NULL, ARRAY['Sit on a bench or chair with your feet flat on the ground and your back straight.', 'Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.', 'Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.', 'Repeat for the desired number of repetitions, then switch to the other hand.']::text[], FALSE),
  ('single-arm-dumbbell-wrist-curl', 'Single-Arm Dumbbell Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-arm-dumbbell-wrist-curl.gif', NULL, NULL, ARRAY['Sit on a flat bench with a dumbbell in your right hand.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.', 'Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position.', 'Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.', 'Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.']::text[], FALSE),
  ('seated-neutral-dumbbell-wrist-curl', 'Seated Neutral Dumbbell Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-neutral-dumbbell-wrist-curl.gif', NULL, NULL, ARRAY['Start out by placing two dumbbells on the floor in front of a flat bench.', 'Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.', 'Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.']::text[], FALSE),
  ('cable-wrist-curl', 'Cable Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-wrist-curl.gif', NULL, NULL, ARRAY['Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.', 'Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.', 'Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.']::text[], FALSE),
  ('cable-reverse-wrist-curl', 'Cable Reverse Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-reverse-wrist-curl.gif', NULL, NULL, ARRAY['Attach a cable to a low pulley and sit on a bench facing the cable machine.', 'Grasp the cable handle with an overhand grip, palms facing down.', 'Rest your forearms on your thighs, with your wrists hanging off the edge.', 'Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.', 'Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.']::text[], FALSE),
  ('smith-behind-back-wrist-curl', 'Smith Machine Behind-Back Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'smith_machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/smith-behind-back-wrist-curl.gif', NULL, NULL, ARRAY['Stand facing the smith machine with your feet shoulder-width apart.', 'Grasp the barbell with an overhand grip, hands shoulder-width apart.', 'Keep your back straight and your elbows close to your body.', 'Slowly curl your wrists upwards, bringing the barbell towards your body.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.']::text[], FALSE),
  ('wrist-roller', 'Wrist Roller', 'forearms'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'other'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/wrist-roller.gif', NULL, NULL, ARRAY['To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.', 'Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position.', 'Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.', 'Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position.', 'Repeat for the prescribed amount of repetitions in your program.']::text[], FALSE),
  ('dumbbell-farmers-walk', 'Dumbbell Farmer''s Walk', 'forearms'::public.muscle_group, ARRAY['back', 'quads', 'core']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-farmers-walk.gif', NULL, NULL, ARRAY['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.', 'After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.', 'Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.']::text[], FALSE),
  ('treadmill-run', 'Treadmill Run', 'cardio'::public.muscle_group, ARRAY['quads', 'hamstrings', 'calves']::public.muscle_group[], 'cardio_machine'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/treadmill-run.gif', '/exercises/photos/treadmill-run-0.jpg', '/exercises/photos/treadmill-run-1.jpg', ARRAY['Step onto the side rails, start the belt at a slow walking pace, and clip the safety key to your shirt.', 'Increase speed and incline gradually to your target pace before settling into a tall, relaxed running posture.', 'Land lightly midfoot underneath your center of mass while swinging your arms naturally at roughly 90 degrees.', 'Reduce speed to an easy walk for 2 to 3 minutes to cool down before bringing the belt to a complete stop.']::text[], FALSE),
  ('incline-treadmill-walk', 'Incline Treadmill Walk', 'cardio'::public.muscle_group, ARRAY['glutes', 'calves', 'hamstrings']::public.muscle_group[], 'cardio_machine'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/incline-treadmill-walk.gif', '/exercises/photos/incline-treadmill-walk-0.jpg', '/exercises/photos/incline-treadmill-walk-1.jpg', ARRAY['Set your target speed first, then raise the treadmill incline to the desired grade without gripping the handrails.', 'Stand tall with a slight natural forward lean from the ankles rather than rounding your lower back.', 'Drive through your glutes and calves with brisk, controlled steps and keep your shoulders relaxed.', 'Lower the incline and slow the belt down smoothly during the final minutes of your session.']::text[], FALSE),
  ('stationary-bike', 'Stationary Bike', 'cardio'::public.muscle_group, ARRAY['quads', 'hamstrings', 'calves']::public.muscle_group[], 'cardio_machine'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/stationary-bike.gif', '/exercises/photos/stationary-bike-0.jpg', '/exercises/photos/stationary-bike-1.jpg', ARRAY['To begin, seat yourself on the bike and adjust the seat to your height.', 'Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[], FALSE),
  ('recumbent-bike', 'Recumbent Bike', 'cardio'::public.muscle_group, ARRAY['quads', 'glutes']::public.muscle_group[], 'cardio_machine'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/recumbent-bike.gif', '/exercises/photos/recumbent-bike-0.jpg', '/exercises/photos/recumbent-bike-1.jpg', ARRAY['To begin, seat yourself on the bike and adjust the seat to your height.', 'Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.', 'Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running.']::text[], FALSE),
  ('air-bike', 'Air Bike (Assault Bike)', 'cardio'::public.muscle_group, ARRAY['quads', 'shoulders', 'core']::public.muscle_group[], 'cardio_machine'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/air-bike.gif', NULL, NULL, ARRAY['Adjust the seat height so your knee retains a slight bend at the bottom of the pedal stroke.', 'Grip the moving handles firmly and coordinate strong push-pull arm strokes with steady downward pedal drives.', 'Remember that fan resistance scales automatically with your cadence, making hard intervals noticeably heavier.', 'Maintain tall posture and rhythmic breathing through sustained aerobic pieces or sprint intervals.']::text[], FALSE),
  ('rowing-ergometer', 'Rowing Ergometer (Row Erg)', 'cardio'::public.muscle_group, ARRAY['back', 'quads', 'core']::public.muscle_group[], 'cardio_machine'::public.equipment_type, 'cardio'::public.tracking_type, NULL, '/exercises/photos/rowing-ergometer-0.jpg', '/exercises/photos/rowing-ergometer-1.jpg', ARRAY['Strap your feet securely over the balls of your feet and set the damper lever to your target resistance level.', 'Begin the drive by pushing hard through your legs while keeping your arms straight and torso braced at a slight forward angle.', 'Once your legs nearly extend, hinge back slightly and pull the handle cleanly toward your lower ribs.', 'Reverse the sequence smoothly on the recovery: extend your arms forward first, hinge at the hips, then bend your knees to the catch.']::text[], FALSE),
  ('stair-climber', 'Stair Climber', 'cardio'::public.muscle_group, ARRAY['quads', 'glutes', 'calves']::public.muscle_group[], 'cardio_machine'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/stair-climber.gif', '/exercises/photos/stair-climber-0.jpg', '/exercises/photos/stair-climber-1.jpg', ARRAY['To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall.', 'Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outside while offering a similar rate of calories burned. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.']::text[], FALSE),
  ('elliptical-trainer', 'Elliptical Trainer', 'cardio'::public.muscle_group, ARRAY['quads', 'glutes', 'shoulders']::public.muscle_group[], 'cardio_machine'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/elliptical-trainer.gif', '/exercises/photos/elliptical-trainer-0.jpg', '/exercises/photos/elliptical-trainer-1.jpg', ARRAY['To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[], FALSE),
  ('skierg', 'SkiErg', 'cardio'::public.muscle_group, ARRAY['back', 'triceps', 'core']::public.muscle_group[], 'cardio_machine'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/skierg.gif', NULL, NULL, ARRAY['Stand roughly arm''s length back from the SkiErg frame with your feet shoulder-width apart and grip both handles.', 'Set the flywheel damper resistance, reach overhead to start tall, and brace your core.', 'Pull the handles downward forcefully while hinging at the hips and engaging your lats, core, and triceps.', 'Let your arms float smoothly back up to the starting position while resetting your torso tall before the next pull.']::text[], FALSE),
  ('arm-ergometer', 'Arm Ergometer (Hand Bike)', 'cardio'::public.muscle_group, ARRAY['shoulders', 'back', 'core']::public.muscle_group[], 'cardio_machine'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/arm-ergometer.gif', NULL, NULL, ARRAY['Adjust the seat height and handlebar position to a comfortable level.', 'Sit on the ergometer with your back straight and feet on the pedals.', 'Grasp the handles with your hands and position your arms at a 90-degree angle.', 'Start pedaling with your hands, pushing and pulling the handles in a controlled motion.', 'Continue pedaling for the desired duration or number of repetitions.']::text[], FALSE),
  ('jump-rope', 'Jump Rope', 'cardio'::public.muscle_group, ARRAY['calves', 'shoulders', 'core']::public.muscle_group[], 'other'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/jump-rope.gif', '/exercises/photos/jump-rope-0.jpg', '/exercises/photos/jump-rope-1.jpg', ARRAY['Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.', 'Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running.']::text[], FALSE),
  ('outdoor-run', 'Outdoor Run', 'cardio'::public.muscle_group, ARRAY['quads', 'hamstrings', 'calves']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/outdoor-run.gif', '/exercises/photos/outdoor-run-0.jpg', '/exercises/photos/outdoor-run-1.jpg', ARRAY['Begin with a 5-minute brisk walk or easy jog to warm up your ankles, calves, and hips.', 'Maintain an upright torso, relaxed shoulders, and a smooth cadence with feet landing beneath your hips.', 'Adjust pace smoothly on hills to keep effort controlled during steady runs or intervals.', 'Taper into a walk for the final 2 to 3 minutes to bring your heart rate down smoothly.']::text[], FALSE),
  ('outdoor-cycling', 'Outdoor Cycling', 'cardio'::public.muscle_group, ARRAY['quads', 'glutes', 'calves']::public.muscle_group[], 'other'::public.equipment_type, 'cardio'::public.tracking_type, NULL, '/exercises/photos/outdoor-cycling-0.jpg', '/exercises/photos/outdoor-cycling-1.jpg', ARRAY['Check tire pressure, brakes, and saddle height before setting off so your knee has a slight bend at the bottom stroke.', 'Shift gears early ahead of inclines to keep your pedaling cadence smooth rather than grinding heavy gears.', 'Keep your elbows softly bent, shoulders relaxed, and eyes scanning ahead for road hazards.']::text[], FALSE),
  ('sled-push', 'Sled Push (Prowler Sprint)', 'cardio'::public.muscle_group, ARRAY['quads', 'glutes', 'calves', 'core']::public.muscle_group[], 'other'::public.equipment_type, 'cardio'::public.tracking_type, NULL, '/exercises/photos/sled-push-0.jpg', '/exercises/photos/sled-push-1.jpg', ARRAY['Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.', 'You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.', 'With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.']::text[], FALSE),
  ('burpee', 'Burpee', 'cardio'::public.muscle_group, ARRAY['chest', 'quads', 'core']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/burpee.gif', NULL, NULL, ARRAY['Start in a standing position with your feet shoulder-width apart.', 'Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.', 'Kick your feet back into a push-up position.', 'Perform a push-up, keeping your body in a straight line.', 'Jump your feet back into the squat position.']::text[], FALSE),
  ('mountain-climber', 'Mountain Climber', 'cardio'::public.muscle_group, ARRAY['core', 'shoulders', 'quads']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'cardio'::public.tracking_type, '/exercises/gifs/mountain-climber.gif', NULL, NULL, ARRAY['Start in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.', 'Continue alternating legs in a running motion, keeping your hips low and your core engaged.', 'Maintain a steady pace and breathe evenly throughout the exercise.', 'Repeat for the desired number of repetitions.']::text[], FALSE)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  muscle_group = EXCLUDED.muscle_group,
  secondary_muscles = EXCLUDED.secondary_muscles,
  equipment = EXCLUDED.equipment,
  tracking_type = EXCLUDED.tracking_type,
  media_gif_url = EXCLUDED.media_gif_url,
  media_image_start_url = EXCLUDED.media_image_start_url,
  media_image_end_url = EXCLUDED.media_image_end_url,
  instructions = EXCLUDED.instructions,
  is_custom = FALSE,
  archived_at = NULL;

SELECT public.bump_sync_domain('exercises');
